CREATE TABLE `notification_preferences` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`user_id` CHAR(36) CHARACTER SET ascii NOT NULL,`in_app_enabled` TINYINT(1) NOT NULL DEFAULT 1,`email_enabled` TINYINT(1) NOT NULL DEFAULT 0,`task_enabled` TINYINT(1) NOT NULL DEFAULT 1,`approval_enabled` TINYINT(1) NOT NULL DEFAULT 1,`competitor_enabled` TINYINT(1) NOT NULL DEFAULT 1,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_notification_preference_scope`(`organization_id`,`workspace_id`,`user_id`),CONSTRAINT `fk_notification_preference_user` FOREIGN KEY(`user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `notifications` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`recipient_id` CHAR(36) CHARACTER SET ascii NOT NULL,`source_event_id` CHAR(36) CHARACTER SET ascii NOT NULL,`category` ENUM('task','approval','competitor','system') NOT NULL,`severity` ENUM('info','warning','critical') NOT NULL DEFAULT 'info',`title` VARCHAR(200) NOT NULL,`body` VARCHAR(2000) NOT NULL,`resource_type` VARCHAR(80) CHARACTER SET ascii NULL,`resource_id` CHAR(36) CHARACTER SET ascii NULL,`read_at` DATETIME(3) NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_notification_event_recipient`(`source_event_id`,`recipient_id`),KEY `idx_notification_inbox`(`organization_id`,`workspace_id`,`recipient_id`,`read_at`,`created_at`),CONSTRAINT `fk_notification_recipient` FOREIGN KEY(`recipient_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_notification_event` FOREIGN KEY(`source_event_id`) REFERENCES `outbox_events`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `notification_deliveries` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`notification_id` CHAR(36) CHARACTER SET ascii NOT NULL,`recipient_id` CHAR(36) CHARACTER SET ascii NOT NULL,`channel` ENUM('in_app','email') NOT NULL,`status` ENUM('delivered','pending_placeholder','suppressed','failed','dead_letter') NOT NULL,`attempt_count` INT UNSIGNED NOT NULL DEFAULT 0,`provider_ref` VARCHAR(200) NULL,`last_error_code` VARCHAR(120) NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_notification_delivery_channel`(`notification_id`,`channel`),KEY `idx_notification_delivery_status`(`status`,`updated_at`),CONSTRAINT `fk_notification_delivery_notification` FOREIGN KEY(`notification_id`) REFERENCES `notifications`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `notification_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route_key` VARCHAR(180) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(128) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_json` JSON NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_notification_operation`(`actor_id`,`route_key`,`idempotency_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
